-- Academy configuration foundation: buildings, rooms and tables.
create table if not exists public.academy_buildings (id uuid primary key default gen_random_uuid(), name text not null unique, address text, status text not null default 'active' check(status in ('active','inactive')), created_at timestamptz not null default now());
create table if not exists public.academy_rooms (id uuid primary key default gen_random_uuid(), building_id uuid not null references public.academy_buildings(id) on delete restrict, name text not null, room_type text not null default 'group' check(room_type in ('group','tutor','other')), capacity smallint, status text not null default 'active' check(status in ('active','inactive')), created_at timestamptz not null default now(), unique(building_id,name));
create table if not exists public.academy_tables (id uuid primary key default gen_random_uuid(), room_id uuid not null references public.academy_rooms(id) on delete restrict, name text not null, table_number smallint, seat_capacity smallint not null default 6 check(seat_capacity between 1 and 40), status text not null default 'active' check(status in ('active','inactive')), created_at timestamptz not null default now(), unique(room_id,name));
alter table public.academy_buildings enable row level security; alter table public.academy_rooms enable row level security; alter table public.academy_tables enable row level security;
revoke all on public.academy_buildings,public.academy_rooms,public.academy_tables from anon,authenticated; grant all on public.academy_buildings,public.academy_rooms,public.academy_tables to service_role;
with building as (insert into public.academy_buildings(name) values ('The Afternoon Academy') on conflict(name) do update set name=excluded.name returning id), taa1 as (insert into public.academy_rooms(building_id,name,room_type,capacity) select id,'TAA1','group',12 from building on conflict(building_id,name) do update set room_type='group',capacity=12 returning id)
insert into public.academy_tables(room_id,name,table_number,seat_capacity) select id,'Table 1',1,6 from taa1 union all select id,'Table 2',2,6 from taa1 on conflict(room_id,name) do update set table_number=excluded.table_number,seat_capacity=excluded.seat_capacity;